import json,pathlib
r=pathlib.Path('.')
def save(n,d): (r/n).write_text(json.dumps(d,indent=2),encoding='utf-8')
rows=[('itemsSold','Garments sold annually',100000,1e10,'setup',None),('avgWeightKg','Average garment weight',.3,20,'setup','averageGarmentWeight'),('baselineCollectionRate','Baseline collection rate',.2,1,'setup','textileCollectionRate'),('baselineRecyclingYield','Baseline recycling yield',.5,1,'setup','textileRecyclingRate'),('participatingCustomers','Participating customers',1000,1e9,'setup',None),('shareOfRangeAffected','Share of range affected',.4,1,'slowingFlows',None),('lifetimeIncreasePct','Increase in garment lifetime',.5,10,'slowingFlows',None),('substitutionRate','Substitution rate',.6,1,'slowingFlows','typicalSubstitutionRate'),('itemsPerPerson','Items in each wardrobe',100,10000,'slowingStocks','itemsPerPerson'),('unwornShare','Wardrobe unworn for a year',.3,1,'slowingStocks','unwornShare'),('shareOfUnwornBroughtIntoUse','Unworn items brought into use',.1,1,'slowingStocks',None),('shareDesignedForRecycling','Designed for recycling',.7,1,'closingFlows',None),('newCollectionRate','New collection rate',.5,1,'closingFlows',None),('fibreToFibreYield','Fibre-to-fibre yield',.6,1,'closingFlows','fibreToFibreRecyclingYield'),('itemsDisposedPerPersonPerYear','Items disposed per person annually',20,1000,'closingStocks','itemsDisposedPerPersonPerYear'),('deltaCollectionRate','Additional collection share',.15,1,'closingStocks',None),('yield','Collected stock recycling yield',.5,1,'closingStocks',None),('pctMaterialSavedPerGarment','Material saved per garment',.05,1,'lifeFlows',None),('pctManufacturingWasteAvoided','Manufacturing waste avoided',0,1,'lifeFlows',None),('preConsumerWasteRate','Pre-consumer waste rate',.1,1,'lifeFlows','preConsumerManufacturingWasteRate'),('reboundFactor','Savings lost to extra consumption',.15,1,'systems','typicalReboundFactor')]
params=[]
for i,label,d,m,g,b in rows:
 unit='share' if m in [1,10] else {'itemsSold':'items/year','avgWeightKg':'kg/item','participatingCustomers':'people','itemsPerPerson':'items/person'}.get(i,'items/person/year')
 params.append(dict(id=i,label=label,default=d,min=.001 if i=='avgWeightKg' else 0,max=m,group=g,benchmark=b,unit=unit,help='Enter a fraction: 0.6 means 60%.' if unit=='share' else 'Use evidence from your business where available.'))
save('data/parameters.json',params)
wrap='https://www.wrap.ngo/resources/report/valuing-our-clothes-true-cost-how-we-design-use-and-dispose-clothing-uk-2012'
bench=[]
for p in params:
 if p['benchmark']:
  for region in ['UK','EU','US']:
   v=p['id']=='unwornShare' and region=='UK'
   bench.append(dict(id=p['benchmark'],label=p['label'],value=p['default'],unit=p['unit'],region=region,year=2012 if v else 2026,sourceName='WRAP, Valuing our clothes' if v else 'Illustrative screening assumption',sourceUrl=wrap if v else '',retrievedOn='2026-10-21',verified=v,notes='Around 30% of clothing unworn for at least a year.' if v else 'UNVERIFIED, replace before publishing. Illustrative placeholder, not an observed regional average.'))
bench.append(dict(id='epaTextileRecyclingContext',label='US all-textile recycling rate (context only)',value=.147,unit='share',region='US',year=2018,sourceName='US EPA',sourceUrl='https://19january2021snapshot.epa.gov/facts-and-figures-about-materials-waste-and-recycling/textiles-material-specific-data_.html',retrievedOn='2026-10-21',verified=True,notes='Overall recycling rate, NOT conditional or fibre-to-fibre yield. Not used in formulas.'))
save('data/benchmarks.json',bench)
save('data/confidence.json',dict(low=.5,medium=.25,high=.1))
qs=[('slowingFlows','Slowing','Flows',['Does it increase the useful lifetime of new garments (e.g. through maintenance and care, repair, re-manufacture, reuse)?','Does it reduce total new garment production?']),('slowingStocks','Slowing','Stocks',['Does it reduce the total number of items in the UK wardrobe?','Does it lead consumers to better use their own existing wardrobe? Will it make them buy less as a result?','Does it lead to the stock of clothing being used better in general (e.g. by others, UK, abroad)?','Does it have the ability to reverse trends of clothing overconsumption?']),('closingFlows','Closing','Flows',['Does it increase the recyclability of new COMPANY clothes being manufactured?','Does it increase recycling rates for new COMPANY clothes being manufactured?']),('closingStocks','Closing','Stocks',['Does it increase the recyclability of the existing clothing stock?','Does it increase the number of clothing items from the UK wardrobe given away for recycling?','Does it have ability to reverse trends of textiles going to landfill?']),('lifeFlows','Life cycle','Flows',['Does it lead to any design efficiencies (e.g. less material per product)?','Does it lead to any manufacturing efficiencies?','Does it lead to any transportation savings?','Does it lead to more efficient or less cleaning?','Does it lead to cleaner forms of recycling not captured yet?','Does it lead to any other efficiencies not yet captured?']),('lifeStocks','Life cycle','Stocks',['Does it lead to any transportation savings for handling the current clothing stock?','Does it lead to more efficient or less cleaning for the current clothing stock?','Does it lead to any other efficiency/ savings (e.g. ironing, tumble drying) not yet captured for current clothing stocks?']),('systems','Systems','Both',['Does it lead to negative rebound effects (e.g. consuming more) or positive ones (e.g. from fast to slow fashion)?','Are there any unintended consequences by upcycling the value of waste?','Does it lead to radical changes for stores and employees? What are the impacts on those stakeholders and others? Who are the potential winners/ losers?','What is the effect of multiple co-existing business models?','What is the impact on society of this innovation?','What is required for other companies to follow - is that considered in this new business model?'])]
save('data/questions.json',[dict(id=i,effect=e,column=c,questions=q,parameters=[p['id'] for p in params if p['group']==i]) for i,e,c,q in qs])
f={'baseline':'itemsSold*avgWeightKg*(1-baselineCollectionRate*baselineRecyclingYield)/1000','slowingFlows':'itemsSold*shareOfRangeAffected*avgWeightKg*(1-1/(1+lifetimeIncreasePct))*substitutionRate*(1-reboundFactor)/1000','slowingStocks':'participatingCustomers*itemsPerPerson*unwornShare*shareOfUnwornBroughtIntoUse*substitutionRate*avgWeightKg*(1-reboundFactor)/1000','closingFlows':'MAX(0,itemsSold*avgWeightKg*(shareDesignedForRecycling*newCollectionRate*fibreToFibreYield-baselineCollectionRate*baselineRecyclingYield)/1000)*(1-reboundFactor)*(1-shareOfRangeAffected*(1-1/(1+lifetimeIncreasePct))*substitutionRate)','closingStocks':'participatingCustomers*itemsDisposedPerPersonPerYear*deltaCollectionRate*yield*avgWeightKg*(1-reboundFactor)/1000*(1-MIN(1,itemsPerPerson*unwornShare*shareOfUnwornBroughtIntoUse*substitutionRate/MAX(0.000001,itemsDisposedPerPersonPerYear))))','lifeFlows':'itemsSold*shareOfRangeAffected*avgWeightKg*(pctMaterialSavedPerGarment+preConsumerWasteRate*pctManufacturingWasteAvoided)/1000'}
save('data/formulas.json',f)
base={p['id']:p['default'] for p in params}
ex=[]
for name,patch in [('Clothing rental',dict(lifetimeIncreasePct=1)),('Resale / take-back',dict(newCollectionRate=.8,shareOfUnwornBroughtIntoUse=.2)),('Repair and care service',dict(lifetimeIncreasePct=.8,shareDesignedForRecycling=0,pctMaterialSavedPerGarment=0)),('Recycled-fibre range',dict(shareDesignedForRecycling=1,newCollectionRate=.8,fibreToFibreYield=.8,lifetimeIncreasePct=0,shareOfUnwornBroughtIntoUse=0))]:
 ex.append(dict(version=1,name=name,description='Illustrative inputs only; not claims about real companies.',region='UK',inputs=base|patch,confidence={q[0]:'medium' for q in qs},bands=dict(low=.5,medium=.25,high=.1),mode='conservative',confirmed=dict(substitutionRate=True,reboundFactor=True),checklist=[.5,.5,.5],notes=[dict(text='',risk='medium') for _ in range(6)]))
save('data/examples.json',ex)
save('data/settings.json',dict(sensitivityFraction=.2,radarMaximum=100,maxScenarios=3,steps=['Welcome','Setup','Business model','Slowing','Closing','Life cycle','Systems','Results','Export']))
